import { GetObjectCommand, PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";

const [method, key, seconds = "900"] = process.argv.slice(2);
const s3 = new S3Client({ region: "us-east-1", forcePathStyle: true });
const Command = method === "PUT" ? PutObjectCommand : GetObjectCommand;

const url = await getSignedUrl(s3, new Command({ Bucket: "rhino-ai-agents-runs", Key: key }), {
  expiresIn: Number(seconds),
});
console.log(url);
